import json,collections
from pathlib import Path
for d in ('13','14'):
 for p in sorted((Path('/home/user/.codex/sessions/2026/11')/d).glob('*.jsonl')):
  c=collections.Counter(); times=[]
  for line in p.read_text().splitlines():
   r=json.loads(line)
   if r.get('type')=='event_msg': c[r.get('payload',{}).get('type')]+=1
   if r.get('type')=='response_item':
    q=r.get('payload',{}); c[(q.get('type','')+':'+q.get('role','')+':'+str(q.get('channel','')))]+=1
   if r.get('timestamp'): times.append(r['timestamp'])
  print(p.name, json.dumps(dict(c)), min(times),max(times))
